mapper.select:
select

from profile_meta_task
where 1 = 1

  and status = #{status,jdbcType=TINYINT}


  and task_name = #{taskName,jdbcType=VARCHAR}


  and task_desc = #{taskDesc,jdbcType=VARCHAR}


  and task_type = #{taskType,jdbcType=INTEGER}


  and task_related_id = #{taskRelatedId,jdbcType=VARCHAR}


  and trigger_target_id = #{triggerTargetId,jdbcType=VARCHAR}


  and trigger_type = #{triggerType,jdbcType=INTEGER}


  and trigger_cron = #{triggerCron,jdbcType=VARCHAR}


  and trigger_url = #{triggerUrl,jdbcType=VARCHAR}


  and trigger_start_time = #{triggerStartTime,jdbcType=VARCHAR}


  and trigger_end_time = #{triggerEndTime,jdbcType=VARCHAR}


  and source_type = #{sourceType,jdbcType=INTEGER}


  and owner = #{owner,jdbcType=VARCHAR}


  and creator = #{creator,jdbcType=VARCHAR}


  and modifier = #{modifier,jdbcType=VARCHAR}


  and gmt_create = #{gmtCreate,jdbcType=TIMESTAMP}


  and gmt_modified = #{gmtModified,jdbcType=TIMESTAMP}
